1	/* 8x8x8 integer GEMM: C = A * B.
2	 * The kernel is RISC-V RVV intrinsics; a plain-C version verifies it. */
3	#include <stdio.h>
4	#include <stdint.h>
5	#include <riscv_vector.h>
6	
7	#define N 8
8	
9	static int32_t A[N][N], B[N][N], C[N][N], C_ref[N][N];
10	
11	/* init: fill A and B with small signed values (plain C). */
12	static void init_matrices(void)
13	{
14	  for (int i = 0; i < N; i++)
15	    for (int j = 0; j < N; j++) {
16	      A[i][j] = (i + j) % 7 - 3;
17	      B[i][j] = (i * 3 + j) % 5 - 2;
18	    }
19	}
20	
21	/* RVV kernel: row accumulation, C[i][:] += A[i][k] * B[k][:].
22	 * One row of 8 int32 lanes fits in one vector register (vl = 8).
23	 * noinline keeps the whole kernel inside the ROI marker span and gives
24	 * the PC-trigger mode a symbol to anchor on. */
25	static void __attribute__((noinline)) gemm_rvv(void)
26	{
27	  size_t vl = __riscv_vsetvl_e32m1(N);
28	  for (int i = 0; i < N; i++) {
29	    vint32m1_t acc = __riscv_vmv_v_x_i32m1(0, vl);
30	    for (int k = 0; k < N; k++) {
31	      vint32m1_t brow = __riscv_vle32_v_i32m1(B[k], vl);
32	      acc = __riscv_vmacc_vx_i32m1(acc, A[i][k], brow, vl);
33	    }
34	    __riscv_vse32_v_i32m1(C[i], acc, vl);
35	  }
36	}
37	
38	/* reference: the same GEMM in plain C. */
39	static void gemm_c(void)
40	{
41	  for (int i = 0; i < N; i++)
42	    for (int j = 0; j < N; j++) {
43	      int32_t s = 0;
44	      for (int k = 0; k < N; k++) s += A[i][k] * B[k][j];
45	      C_ref[i][j] = s;
46	    }
47	}
48	
49	int main(void)
50	{
51	  init_matrices();
52	
53	  gemm_rvv();
54	
55	  gemm_c();
56	  int errors = 0;
57	  for (int i = 0; i < N; i++)
58	    for (int j = 0; j < N; j++)
59	      if (C[i][j] != C_ref[i][j]) errors++;
60	  if (errors) printf("FAIL: %d mismatches\n", errors);
61	  else printf("PASS: 8x8x8 RVV GEMM matches the C reference\n");
62	  return errors != 0;
